  const handleEmailVerify=async()=>{ setVerifyError(''); const config=getCollegeConfig(); if(!config) return; const emailLower=collegeEmail.toLowerCase().trim(); if(!config.domains.some(d=>emailLower.endsWith(d))){ setVerifyError(`Only ${config.domains.join(' or ')} allowed - SRET ONLY 🔒`); return; } if(BLOCKED_DOMAINS.some(d=>emailLower.includes(d))){ setVerifyError(`Fake mail blocked - Use SRET mail only`); return; } if(!/^[a-zA-Z0-9._%+-]+@sret\.(edu\.in|ac\.in)$/.test(emailLower)){ setVerifyError(`Invalid SRET email - 21cs101@sret.edu.in`); return; } const dup=await getDocs(query(collection(db,'users'),where('collegeEmail','==',emailLower))); if(!dup.empty){ setVerifyError('Email already used'); return; } const deviceId=localStorage.getItem('sret_device_id'); const deviceDup=await getDocs(query(collection(db,'users'),where('deviceId','==',deviceId))); if(!deviceDup.empty){ setVerifyError(`Device already has account`); return; } const otpCode=Math.floor(100000+Math.random()*900000).toString(); setGeneratedOtp(otpCode); await setDoc(doc(db,'email_otps',emailLower),{email:emailLower,otp:otpCode,deviceId,attempts:0,createdAt:serverTimestamp(),expiresAt:new Date(Date.now()+5*60*1000)}); setOtpSent(true); showToast("OTP: "+otpCode+" - 5 min valid 🔒"); };
  const handleOtpSubmit=async()=>{ const emailLower=collegeEmail.toLowerCase().trim(); const snap=await getDocs(query(collection(db,'email_otps'),where('email','==',emailLower))); if(snap.empty){ setVerifyError('OTP expired - Request new'); return; } const d=snap.docs[0].data() as any; const createdAt=d.createdAt?.toDate?d.createdAt.toDate():new Date(); if((Date.now()-createdAt.getTime())/1000/60>5){ await deleteDoc(doc(db,'email_otps',emailLower)); setVerifyError('OTP expired 5 min'); setOtpSent(false); return; } if(d.attempts>=3){ await deleteDoc(doc(db,'email_otps',emailLower)); setVerifyError('Too many attempts - Blocked'); return; } if(d.otp!==otp.trim()){ await updateDoc(doc(db,'email_otps',emailLower),{attempts:increment(1)}); setVerifyError(`Wrong OTP - ${2-(d.attempts||0)} left`); return; } await deleteDoc(doc(db,'email_otps',emailLower)); localStorage.setItem('college_email',emailLower); localStorage.setItem('verify_method','email'); setIsVerified(true); setScreen('login'); };
  const handleRollVerify=async()=>{ setVerifyError(''); const config=getCollegeConfig(); if(!config) return; const rollUpper=rollNumber.trim().toUpperCase(); if(!config.pattern.test(rollUpper)){ setVerifyError(`Invalid Roll - Ex: ${config.ex}`); return; } const year=parseInt(rollUpper.substring(0,2)); if(year<20||year>25){ setVerifyError(`Only 2020-2025`); return; } const dup=await getDocs(query(collection(db,'users'),where('rollNumber','==',rollUpper))); if(!dup.empty){ setVerifyError('Roll already used'); return; } const deviceId=localStorage.getItem('sret_device_id'); const deviceDup=await getDocs(query(collection(db,'users'),where('deviceId','==',deviceId))); if(!deviceDup.empty){ setVerifyError(`Device already has account`); return; } localStorage.setItem('roll_number',rollUpper); localStorage.setItem('verify_method','roll'); setIsVerified(true); setScreen('login'); };
