  const handleReport=async(y:any, reason:string)=>{ if(!userData) return; if(userData.reportedPosts?.includes(y.id)){ showToast("Already reported"); return; } try{ await addDoc(collection(db,'reports'),{yakId:y.id, yakText:y.text.slice(0,200), yakUid:y.uid, reportedBy:user.uid, reason, status:"pending", createdAt:serverTimestamp()}); await updateDoc(doc(db,'yaks',y.id),{reports:increment(1)}); await updateDoc(doc(db,'users',userData.id),{reportedPosts:arrayUnion(y.id)}); if((y.reports||0)+1>=5){ await updateDoc(doc(db,'yaks',y.id),{hidden:true}); showToast("Hidden - Admin review 👑"); } else showToast(`Reported ${ (y.reports||0)+1}/5 - Anonymous`); setShowMenu(null); }catch(e:any){ showToast(e.message); } };
  const buildTree=(flat:any[])=>{ const map:Record<string,any>={}; const roots:any[]=[]; flat.forEach(c=>{ map[c.id]={...c, replies:[]}; }); flat.forEach(c=>{ if(c.parentId && map[c.parentId]){ map[c.parentId].replies.push(map[c.id]); } else { roots.push(map[c.id]); } }); return roots; };
